def has_cycle(n, edges):
    g = [[] for _ in range(n)]
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    seen = [False] * n
    for s in range(n):
        if seen[s]:
            continue
        seen[s] = True
        stack = [(s, -1)]
        while stack:
            v, parent = stack.pop()
            for w in g[v]:
                if w == parent:
                    continue
                if seen[w]:
                    return True
                seen[w] = True
                stack.append((w, v))
    return False

